insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('087fa7b0-c31d-5fed-9809-6ef2afb95f44', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Which choice completes the text with the most logical and precise word or phrase?', '["efficiency of", "need for", "expense of", "limitation on"]'::jsonb, 1, 'While some people believe they can reduce monthly air-conditioning costs simply by closing air registers in vacant rooms, this practice can actually reduce the ______ climate-control systems by creating internal pressure imbalances that restrict airflow across critical components and force motors to work harder.'),
  ('daed12da-9352-51f7-8ca0-6049749352bd', '416c1917-8310-5ba8-b616-23bb35f5c004', 'As used in the text, what does the word “end” most nearly mean?', '["Decision", "Edge", "Postponement", "Purpose"]'::jsonb, 2, 'The following text is adapted from Jhumpa Lahiri’s 2003 novel The Namesake. Gogol has recently begun working at an architecture firm in New York.

His contributions are incidental, and never fully his own: a stairwell, a skylight, a corridor, an air-conditioning duct. Still, he knows that each component of a building, however small, is nevertheless essential, and he finds it gratifying that after all his years of schooling, all his crits [reviews] and unbuilt projects, his efforts are to have some practical <u>end</u>.'),
  ('214fc2c4-2d55-5383-9f83-345c7e07512f', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Which choice completes the text with the most logical and precise word or phrase?', '["consternation", "anticipation", "incredulity", "gratification"]'::jsonb, 3, 'A study by Peggy Liu and colleagues suggests that people underestimate the ______ they spark by unexpectedly reaching out to a social contact, particularly after a long period of no interaction. Not only are recipients of even simple gestures of affinity (e.g., a text message saying “hello”) pleased by the gestures, that pleasure is largely commensurate with the recipients'' degree of surprise.'),
  ('937d99a8-6345-53ed-8d03-53ab9c466f93', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Which choice completes the text with the most logical and precise word or phrase?', '["distinguish", "promote", "derive", "withdraw"]'::jsonb, 4, 'Along with traditional Japanese forms of woodwork and weaving, sashiko embroidery was revived during the mingei (folk art) movement of the twentieth century. Sashiko’s functional origins as a mending technique and its use of motifs inspired by everyday life, such as yabane (arrow feather), reflect the principle that folk art should ______ its form and themes from the lives of its creators.'),
  ('d4523586-d9ee-5c12-80b9-44f51593ad7f', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Which choice completes the text with the most logical and precise word or phrase?', '["rigor", "novelty", "shallowness", "obscurity"]'::jsonb, 5, 'The dinosaur displays at museums such as the Naturmuseum Senckenberg in Frankfurt (which has a life-sized Diplodocus longus statue among its holdings) are notable for the ______ of the research behind them—the museum staff consulted numerous sources to ensure the accuracy of the displays.'),
  ('a24a17b2-e551-5722-9027-6d141dfb25c5', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Which choice best states the main purpose of the text?', '["To praise the actors who starred in the original version of Mean Girls", "To compare movie theaters in the United States to movie theaters in other countries", "To criticize the cost of making movies in the United States", "To explain the success of advertising for the Mean Girls remake"]'::jsonb, 6, 'The 2024 movie Mean Girls, a remake of the 2004 cult classic, earned over \$28 million during its first weekend in US theaters. One reason for its popularity is that the movie’s marketing team used the internet to introduce new viewers to the original story before the remake was released. The marketers uploaded the original film divided into 23 short segments to a social media site popular with teenagers. The entire film received at least 750,000 views in one day, and 100,000 people started following the “Mean Girls” social media account.'),
  ('054bdaca-553c-55f2-99ad-26e5669829df', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Which choice best describes the overall structure of the text?', '["It introduces an imaging technique that served as the precursor to a newer technique, describes how the older imaging technique was modified to create the newer technique, and then explains a key benefit of the newer technique.", "It implies that an existing imaging technique for studying DNA samples has become obsolete, proposes that this technique be modified to incorporate elements of a different imaging technique, and then predicts the potential impact of the resulting hybrid technique.", "It describes the role of an innovative technique that is used in studying DNA samples, notes that this technique can also be used in analysis of cellular structures, and then emphasizes this technique’s superiority to conventional microscope imaging.", "It explains the primary function of an older imaging technique, introduces a novel imaging technique that compensates for the original technique’s limitations, and then reveals that the same researchers were responsible for developing both techniques."]'::jsonb, 7, 'A 2021 paper by Andrew Payne et al. introduced in situ genome sequencing (IGS), which allows simultaneous sequencing and imaging of genomes within biological samples and facilitates analysis of the relationship between a cell’s DNA and structure. Integrating IGS with expansion microscopy, which uses polymers to enlarge small structures for imaging, a team led by Jason Buenrostro later developed expansion in situ genome sequencing (ExIGS)—a technique that also allows simultaneous sequencing and imaging of genomes, but without the limitations on spatial resolution inherent to IGS.'),
  ('dfec83f3-d9fa-5064-9213-1d0b5364bc20', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Based on the texts, how would the author of Text 2 most likely respond to the underlined claim in Text 1?', '["By noting that there are other benefits to being named a City of Gastronomy besides increased tourism", "By arguing that UNESCO’s recognition of Chengdu was well deserved because of the city’s delicious food", "By suggesting that a significant number of visitors to Chengdu may not know that the city has been officially named a City of Gastronomy", "By claiming that Chengdu’s chefs were mainly responsible for the city’s recognition by UNESCO"]'::jsonb, 8, '**Text 1**
In 2010 Chengdu, China, was named a City of Gastronomy by UNESCO in recognition of the city’s unique food culture. <u>The honor is well known among both residents of the city and tourists who visit.</u> It’s obvious that the selection of Chengdu by UNESCO has brought awareness to local recipes, cooking practices, and chefs and has provided a boost to the city’s tourism industry.

**Text 2**
Many people in Chengdu’s restaurant industry hoped that food tourism would increase after the city was chosen as a City of Gastronomy in 2010. However, as researcher Eerang Park and colleagues argue, cities must still create effective marketing strategies to benefit fully from being named a City of Gastronomy. Without an intentional effort to promote the city’s food scene, many current and potential visitors to Chengdu may not even be aware that it’s home to uniquely delicious food.'),
  ('958663cb-79d7-585f-8553-44ca2413596a', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Which choice best states the main topic of the text?', '["Performances by June Carter Cash in Nashville during the 1900s", "The history of the Grand Ole Opry radio show", "New types of musical instruments used by country music performers", "How AM radio helped country music rise in popularity"]'::jsonb, 9, 'Country music began rising in popularity in the early 1900s largely because of AM radio. Country music radio shows helped launch the careers of many country stars. One of the most influential shows was the Grand Ole Opry, broadcast from Nashville, Tennessee. June Carter Cash sang her hit song “Juke Box Blues” on the show. AM radio helped transform country music into a nationwide sensation and made country icons like Carter Cash household names.'),
  ('ef865115-1b63-54f4-954c-ca0bc53ae200', '416c1917-8310-5ba8-b616-23bb35f5c004', 'What does the text most strongly suggest about the function of the tiyospaye?', '["It operated as a formal network for maintaining cultural practices.", "It functioned primarily as a way to organize hunting activities.", "It served as the central authority for governing society.", "It offered care and protection to all the members it included."]'::jsonb, 10, 'The following text is from Mary Crow Dog’s 1990 autobiography Lakota Woman, written in collaboration with Richard Erdoes.

At the center of the old Sioux society was the tiyospaye, the extended family group, the basic hunting band, which included grandparents, uncles, aunts, in-laws, and cousins. The tiyospaye was like a warm womb cradling all within it. Kids were never alone, always fussed over by not one but several mothers, watched and taught by several fathers.'),
  ('e2cdf1a8-cd65-5f3f-9e22-fe9047b83661', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Which quotation from Flatland most effectively illustrates the claim?', '["“The sizes of the [figures''] sides would of course depend upon the age of the individual... A tall adult Woman might extend to a foot. As to the Males of every class, it may be roughly said that the length of an adult’s size, when added together, is two feet or a little more. But the size of our sides is not under consideration.”", "“Every human being in Flatland is a Regular Figure, that is to say of regular construction. By this I mean that a Woman must not only be a line, but a straight line; that an Artisan or Soldier must have two of his sides equal.”", "“Imagine a vast sheet of paper on which straight Lines, Triangles, Squares, Pentagons, Hexagons, and other figures, instead of remaining fixed in their places, move freely about, on or in the surface, but without the power of rising above or sinking below it, and you will then have a pretty correct notion of my country.”", "“As early as the eleventh century of our era, triangular houses were universally forbidden by Law, the only exceptions being fortifications, [gun]powder magazines, barracks, and other state buildings, which it is not desirable that the general public should approach.”"]'::jsonb, 11, 'Flatland is an 1884 novel by Edwin A. Abbott. The narrator describes the novel’s setting as a world consisting entirely of two-dimensional geometric figures, whose existence is confined to the surface of a plane.'),
  ('d103606f-ef07-590e-899c-93719feadebf', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Which finding, if true, would most directly weaken the hypothesis presented in the text?', '["Given comparable levels of exposure to ZnO-NPs, B. mori accumulates ZnO-NPs at a higher rate than R. rattus does but in a fixed ratio to the rate at which R. rattus does.", "Compared with R. rattus, B. mori can accumulate detectable ZnO-NP concentrations with significantly fewer negative effects.", "B. mori has been shown to accumulate several other types of manufactured nanoparticles in addition to ZnO-NPs, whereas R. rattus has been shown to accumulate only ZnO-NPs.", "ZnO-NP concentrations in B. mori show no reliable correlation with ZnO-NP concentrations in R. rattus when the two species are exposed to similar levels of ZnO-NPs."]'::jsonb, 12, 'Some rubber compounds contain zinc oxide nanoparticles (ZnO-NPs), which can leach into waterways and soils via wastewater. In a 2020 study, Ashiq Hussain Mir and colleagues found that ZnO-NPs can accumulate in the bodies of silkworms (Bombyx mori). While bioaccumulation of manufactured nanoparticles may be inherently worrisome, it has been hypothesized that ZnO-NP bioaccumulation in invertebrates like B. mori could serve a valuable proxy role, obviating the need for manufacturers to conduct costly and intrusive sampling of vertebrate species—such as black rats (Rattus rattus), commonly used in regulatory compliance testing—for nanoparticle bioaccumulation, as environmental protection laws currently require.'),
  ('4b5e3e44-e23e-5688-8b7b-c72d6d72f265', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Which choice most logically completes the text?', '["it is possible to study the roles of L, M, and S cones because each type of cone can be activated without activating the other types.", "L cones react only to wavelengths associated with the color red, S cones react only to wavelengths associated with the color blue, and M cones react only to wavelengths associated with the color green.", "the brain more easily interprets colors in the range both L and M cones react to than in the range both M and S cones react to.", "it is difficult to exclusively study the role of M cones in human vision under natural conditions because M cones can’t be activated without simultaneously activating the L and S cones."]'::jsonb, 13, 'In the retina of the human eye, long (L), medium (M), and short (S) cone cells help process bright light and color by sending signals to the brain. M cones react to a range in the visible spectrum of light that completely overlaps with those L and S cones react to. As a result, ______'),
  ('4f4ca09e-3d39-5edd-bf2f-012b3f24aaae', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Which choice most logically completes the text?', '["the calpine moths likely exemplify a phenomenon in which palatable species gain protection from predators by resembling or mimicking unpalatable or otherwise well-defended species.", "acoustic mimicry is an ineffective defense strategy because bats such as Allen’s big-eared bat are able to discriminate between the ultrasonic pulses of an unpalatable species and those of a palatable mimic.", "the calpine and the dalcerid moths likely exhibit a form of protective mimicry in which two or more unpalatable species develop nearly identical signals to repel predators.", "in both noxious and palatable moths, acoustic aposematic signaling may be more prevalent than previous studies of defenses against bat predation had suggested."]'::jsonb, 14, 'Several moth species—including Cechetra lineosa, a species native to Asia—emit ultrasonic pulses that can function as acoustic aposematic signaling (warning of noxiousness) to Allen’s big-eared bat (Idionycteris phyllotis) and other insectivorous bats, which learn to recognize the ultrasonic signals and avoid preying on the unpalatable moths. Investigating the acoustic properties of defensive ultrasonic pulses in a community of moths in Ecuador, Juliette J. Rubin et al. found that calpine moths that do not produce noxious compounds emit ultrasonic pulses that closely resemble the acoustic aposematic signals of noxious moths in the dalcerid family. The researchers therefore concluded that ______'),
  ('3920274d-ee98-5154-b896-5f0dd7db4472', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Which choice most logically completes the text?', '["emitting the defensive compound enabled plants to keep their stomata open to a greater extent than they otherwise would have.", "plants that emitted the defensive compound converted a greater proportion of captured carbon to carbohydrates than they otherwise would have.", "emitting the defensive compound allowed plants to compensate for stomata closure by fixing carbon more efficiently.", "there may have been underlying genetic differences between the plants that strengthened the correlation between compound emission and photosynthesis efficiency."]'::jsonb, 15, 'Plants often reduce photosynthesis in undamaged parts of their leaves when other parts are being eaten by insects. It appears that feeding triggers the closure of stomata—tiny openings that allow carbon dioxide to enter the leaf—thereby limiting plants'' ability to fix carbon (capture and convert it to carbohydrates during photosynthesis). In a study of genetically identical plants, those that were modified to emit an insect-deterring chemical compound experienced a smaller decline in photosynthesis under insect attack than those that did not emit the compound. Since the two types of plants showed no other differences, this finding suggests that ______'),
  ('51e3c2f9-4b64-52df-b173-b6a98e196a13', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["were", "is", "being", "are"]'::jsonb, 16, 'The perception that a project has no precedent or comparable examples ______ called uniqueness bias. This flawed thinking has the potential to affect project performance significantly, with research showing that uniqueness bias correlates with budget overruns.'),
  ('8cf881f9-a4ac-502f-b8e3-abdeabbfba7c', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["populations which", "populations", "populations, which", "populations,"]'::jsonb, 17, 'In 2022 Willy Delgado, who studies mammals, joined a research team for a 38-day expedition to the remote yet populous region of Alto Mayo, Peru. It had long been assumed that regions with large human ______ were unlikely to yield discoveries of new species, but team members found 27 such species, including a species of semiaquatic mouse belonging to the genus Daptomys.'),
  ('c73fb940-636b-5e34-ab06-0397e938a25f', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["one''s", "they''re", "their", "its"]'::jsonb, 18, 'Rhode Island is one of several US states with legislative provisions for the incorporation of worker cooperatives, businesses in which each worker receives an equal vote in company governance. Skeptics have questioned the co-op model for decades and declared ______ means of governance economically unsustainable, ignoring many examples of successful worker-owned businesses.'),
  ('25c98b70-7809-5650-b149-d92c88cd9c96', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["continue", "has continued", "continues", "to continue"]'::jsonb, 19, 'While pointe shoes, worn by ballerinas so they can balance on their toes, originated as simple satin slippers, some now incorporate modern materials or shock-absorption techniques inspired by athletic footwear: Such innovations, developed to address the increase in physically demanding choreography in modern ballet, ______ the evolution of the pointe shoe that began centuries ago.'),
  ('4cd00f84-e835-5d0d-818e-2c7847c97827', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["fungus.", "fungus,", "fungus", "fungus:"]'::jsonb, 20, 'The mycorrhizal association that occurs between certain fir tree species and the ______ Cenococcum geophilum, commonly referred to as pig truffle, allows the organisms to form extensive symbiotic networks through which nutrients can be exchanged.'),
  ('d7286adb-d3c1-5976-ae3e-7048d5f92184', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Which choice completes the text with the most logical transition?', '["Finally,", "For instance,", "Instead,", "First of all,"]'::jsonb, 21, 'A young bullfrog develops in clear stages. First, it is a small tadpole that uses its tail to swim in ponds. Next, it grows into a large tadpole. Then, tiny back legs begin to appear, and after several weeks, front legs push through the skin. ______ its tail shrinks away completely as the tadpole becomes an adult frog ready for life on land.'),
  ('5d0cb8f8-8ef7-5f20-9595-d39c50e24edf', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Which choice completes the text with the most logical transition?', '["Similarly,", "Furthermore,", "Still,", "In other words,"]'::jsonb, 22, 'Nineteenth-century Modernista architects championed nature in their designs. Granted, the wavy stone facade and ornate floral tilework of Casa Batlló, a Modernista private home designed by Antoni Gaudí, couldn’t exactly grow in a forest. ______ one sees natural influences in Gaudí’s penchant for curves (rather than right angles) and plant- and animal-inspired flourishes.'),
  ('6c4d7aa9-d177-5bb5-8786-6d31c920b354', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Which choice completes the text with the most logical transition?', '["In contrast,", "Then,", "Likewise,", "Specifically,"]'::jsonb, 23, 'The Antikythera Mechanism was an ancient Greek astronomical computer that modeled celestial movements. ______ this remarkable 2,000-year-old invention displayed the cosmos against a zodiac backdrop with rotating pointers and rings indicating the positions of the Sun, Moon, and all five planets known to the ancient Greeks.'),
  ('9d1ab1b9-2f63-5622-98d2-bb6608408987', '416c1917-8310-5ba8-b616-23bb35f5c004', 'Which choice completes the text with the most logical transition?', '["Similarly,", "By contrast,", "Additionally,", "For instance,"]'::jsonb, 24, 'Ancient Athens had a unique form of governing called direct democracy that allowed all citizens to gather, speak, and vote personally on government decisions. ______ citizens of modern countries usually elect representatives to make laws on their behalf because modern countries'' populations are too large for direct democracy to be practical.'),
  ('c04c1c13-c836-5ea5-a19b-46cf02a33b15', '416c1917-8310-5ba8-b616-23bb35f5c004', 'The student wants to say what cranberry juice and mangoes have in common. Which choice best uses information from the notes to do this?', '["Cranberry juice has a pH value that makes it acidic.", "Some acidic substances have pH values of approximately 4.6.", "Cranberry juice and mangoes are both acidic substances.", "Cranberry juice and mangoes have pH values of approximately 3.4."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

Cranberry juice has a pH value of approximately 3.4.
Mangoes have a pH value of approximately 4.6.
Substances with pH values below 7 are acidic.'),
  ('ca52ae59-01bc-572e-8b0b-59608cf99bef', '416c1917-8310-5ba8-b616-23bb35f5c004', 'The student wants to say when black swallowtail butterflies are most active. Which choice best uses information from the notes to do this?', '["Black swallowtail butterflies eat nectar from flowers.", "Some butterflies are black with yellow spots.", "Black swallowtail butterflies are most active during the day.", "The black swallowtail butterfly is a kind of insect."]'::jsonb, 26, 'A student has taken these notes:

Black swallowtail butterflies are black with yellow spots.
They are most active during the day.
They eat nectar from flowers.'),
  ('bcc8d4da-809a-5aba-b3c8-82362eea32ce', '416c1917-8310-5ba8-b616-23bb35f5c004', 'The student wants to describe the process of making and applying the encaustic medium. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The artist creates the medium from wax, resin, and pigment and then spreads it onto a painting surface in layers, heating the layers so that they soften and fuse together.", "Using various tools, the artist mixes the wax and resin, which fuse together in layers.", "After adding pigment for color, the artist applies a mix of wax and resin to a painting surface, at which point patterns are carved into it.", "The artist spreads wax, resin, and pigment onto the encaustic medium (often wood), then applies heat so that they soften and fuse to the previous layers."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

Ezshwan Winding is a Hungarian American artist who specializes in encaustic painting, which follows a multistep process.
Step 1: select and prepare the painting surface (often wood).
Step 2: mix melted wax and resin together and add pigment for color to create the encaustic medium. Step 3: spread the medium on the surface in layers, applying heat to allow each layer to soften and fuse with the previous layers.
Step 4: use various tools to carve patterns into the painting.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('087fa7b0-c31d-5fed-9809-6ef2afb95f44', 0, null, 'Restricted airflow makes the motors work harder, lowering the system''s "efficiency."'),
  ('daed12da-9352-51f7-8ca0-6049749352bd', 3, null, 'His work is to have some practical goal or use: "purpose."'),
  ('214fc2c4-2d55-5383-9f83-345c7e07512f', 3, null, 'Recipients are pleased, and more so when surprised: senders underestimate the "gratification" they cause.'),
  ('937d99a8-6345-53ed-8d03-53ab9c466f93', 2, null, 'Folk art takes its form and themes from everyday life: it should "derive" them from its creators'' lives.'),
  ('d4523586-d9ee-5c12-80b9-44f51593ad7f', 0, null, 'Staff consulted many sources to ensure accuracy: the "rigor" of the research.'),
  ('a24a17b2-e551-5722-9027-6d141dfb25c5', 3, null, 'The text explains how the online marketing made the remake successful.'),
  ('054bdaca-553c-55f2-99ad-26e5669829df', 0, null, 'IGS came first, ExIGS added expansion microscopy to it, and ExIGS removes IGS''s resolution limit.'),
  ('dfec83f3-d9fa-5064-9213-1d0b5364bc20', 2, null, 'Text 2 says many visitors may not know about Chengdu''s food scene, contradicting the claim that the honor is well known.'),
  ('958663cb-79d7-585f-8553-44ca2413596a', 3, null, 'The text explains how AM radio, especially the Grand Ole Opry, spread country music.'),
  ('ef865115-1b63-54f4-954c-ca0bc53ae200', 3, null, 'The tiyospaye was "like a warm womb cradling all within it," with children always cared for.'),
  ('e2cdf1a8-cd65-5f3f-9e22-fe9047b83661', 2, null, 'It describes figures moving on a surface "without the power of rising above or sinking below it."'),
  ('d103606f-ef07-590e-899c-93719feadebf', 3, null, 'A proxy is only useful if silkworm levels predict rat levels; no correlation would undercut it.'),
  ('4b5e3e44-e23e-5688-8b7b-c72d6d72f265', 3, null, 'Because M cones'' range overlaps L and S cones, M cones can''t be triggered alone in normal light.'),
  ('4f4ca09e-3d39-5edd-bf2f-012b3f24aaae', 0, null, 'Harmless calpine moths imitate the warning sounds of noxious moths: a palatable mimic.'),
  ('3920274d-ee98-5154-b896-5f0dd7db4472', 0, null, 'Feeding closes stomata, and the defended plants lost less photosynthesis, so they likely kept stomata more open.'),
  ('51e3c2f9-4b64-52df-b173-b6a98e196a13', 1, null, 'The singular subject "perception" takes "is."'),
  ('8cf881f9-a4ac-502f-b8e3-abdeabbfba7c', 1, null, '"Regions with large human populations" is a restrictive phrase that needs no punctuation.'),
  ('c73fb940-636b-5e34-ab06-0397e938a25f', 3, null, 'The antecedent is the singular "co-op model": "its means of governance."'),
  ('25c98b70-7809-5650-b149-d92c88cd9c96', 0, null, 'The plural subject "innovations" takes "continue."'),
  ('4cd00f84-e835-5d0d-818e-2c7847c97827', 2, null, 'The species name is restrictive, so no punctuation goes between "fungus" and "Cenococcum geophilum."'),
  ('d7286adb-d3c1-5976-ae3e-7048d5f92184', 0, null, 'The last stage in the sequence: "Finally."'),
  ('5d0cb8f8-8ef7-5f20-9595-d39c50e24edf', 2, null, 'Despite the concession, natural influences are still visible: "Still."'),
  ('6c4d7aa9-d177-5bb5-8786-6d31c920b354', 3, null, 'The sentence gives specific details of how it modeled the sky: "Specifically."'),
  ('9d1ab1b9-2f63-5622-98d2-bb6608408987', 1, null, 'Modern representative government contrasts with Athens''s direct democracy.'),
  ('c04c1c13-c836-5ea5-a19b-46cf02a33b15', 2, null, 'Both have pH below 7, so both are acidic.'),
  ('ca52ae59-01bc-572e-8b0b-59608cf99bef', 2, null, 'It states when they are most active: during the day.'),
  ('bcc8d4da-809a-5aba-b3c8-82362eea32ce', 0, null, 'It covers making the medium (wax, resin, pigment) and applying it in heated, fused layers.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

-- PeaklyTest May 2026 · Reading & Writing · Module 2
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('e9ab7ecf-4f0e-5e54-a487-f2960da99315', 'PeaklyTest May 2026 · Reading & Writing · Module 2', 'Reading & Writing', 'Reading & Writing, Module 2 of the May 2026 PeaklyTest · 27 questions · 32 minutes', 32, 141, true, 'PeaklyTest May 2026 · Reading & Writing', 2)
