insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('a6602bac-5b2c-5cf7-bb4b-11ba43d334c5', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', 'Which expression is equivalent to $15(x^{2} - 9)$?', '["$15x^{2} - 135$", "$15x^{2} - 24$", "$15x^{2} - 9$", "$15x^{2} + 6$"]'::jsonb, 1, null),
  ('39895eda-dd32-568e-917e-b093ac0ba492', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', '$f(x) = 4x + 800$
The function shown gives the total cost $f(x)$, in dollars, for making $x$ units of a certain product. What is the total cost, in dollars, for making 100 units of this product?', '["100", "400", "800", "1,200"]'::jsonb, 2, null),
  ('c8586c4f-73eb-588a-8cc1-dd97b80ec549', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', 'A jar has 510 buttons, and $20%$ of these buttons are red. How many buttons in the jar are red?', '[]'::jsonb, 3, null),
  ('f55fd532-0367-5df1-8903-a29bd10d908e', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', 'If the equations $-10x + y = 13$ and $10x + y = 13$ are graphed in the $xy$-plane, at what point $(x,y)$ do the graphs intersect?', '["$(0,13)$", "$(0,10)$", "$(10,0)$", "$(13,0)$"]'::jsonb, 4, null),
  ('3c5bc02c-bcf7-5c20-af3f-7dfa7acd213f', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', 'The graph of $y = (\frac{1}{9})^{x} + 1$ in the $xy$-plane is shifted up 3 units. What is an equation of the resulting graph?', '["$y = (\\frac{1}{9})^{(x+3)} + 1$", "$y = (\\frac{1}{9})^{(x-3)} + 1$", "$y = 3(\\frac{1}{9})^{x} + 1$", "$y = (\\frac{1}{9})^{x} + 4$"]'::jsonb, 5, null),
  ('920df54d-c8d1-5ce5-855d-71c74152b721', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', 'The function $g$ is defined by $g(x) = ∣10x∣ + 18$. What is the value of $g(-6)$?', '[]'::jsonb, 6, null),
  ('fd2dd355-1fca-5f35-8752-03a28f01c12c', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', 'The sides of a rectangle are such that the length is 11 centimeters more than 8 times the width, in centimeters. If the width of the rectangle is 9 centimeters, what is the area, in square centimeters, of the rectangle?', '[]'::jsonb, 7, null),
  ('13f63ded-dfc2-5eb7-bef4-a0a7fe875e49', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', 'Which of the following is the best interpretation of the slope of the line of best fit in this context?', '["The number of tomato seeds planted is predicted to increase by 70 seeds every 100 days.", "The number of tomato seeds planted is predicted to increase by 350 seeds every 100 days.", "The number of tomato seeds that germinate is predicted to increase by 70 seeds for every additional 100 tomato seeds that are planted.", "The number of tomato seeds that germinate is predicted to increase by 350 seeds for every additional 100 tomato seeds that are planted."]'::jsonb, 8, 'A group of 10 gardeners recorded data on the germination rates of their tomato crop for one growing season. The scatterplot shows the relationship between the number of tomato seeds planted, $x$, and the number of tomato seeds that germinated, $y$, for each of the gardeners. A line of best fit is also shown.

![figure](/q/may26/004.webp)'),
  ('40b5c46e-19b7-5919-8ef3-1e798ceb32fa', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', 'The graph of $y = f(x)$ in the $xy$-plane is a line with a slope of 7. What is the slope of the graph of $y =$ $f(x) + 8$ in the $xy$-plane?', '["7", "8", "15", "56"]'::jsonb, 9, null),
  ('8d3a3a5f-3a7c-54e5-89bf-a315c5a8e531', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', '$x + 11 = y(z + 6)$
The given equation relates the distinct positive variables $x$, $y$, and $z$. Which equation correctly represents $z$ in terms of $x$ and $y$?', '["$z = \\frac{x+5}{y}$", "$z = \\frac{x}{y} + 5$", "$z = \\frac{x+11}{y} + 6$", "$z = \\frac{x+11}{y} - 6$"]'::jsonb, 10, null),
  ('67533c94-42b9-53d1-aaa3-8cf052f24b66', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', 'A bookstore is giving away free books every day. The equation $f(x) = 210 - 14x$ gives the number of free books, $f(x)$, that remain to be given away after $x$ days. Which of the following is the best interpretation of $f(15) = 0$ in this context?', '["The bookstore has 15 free books to give away.", "The bookstore will give away 15 free books in 14 days.", "It will take 15 days to give away all the free books.", "It will take 210 days to give away 15 free books."]'::jsonb, 11, null),
  ('72c0ce89-1f3e-5de0-909a-411a5f6c50ef', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', 'The function $f$ is defined by $f(x) = 6x - 3$. If $f(a) + 1 = 5a$, what is the value of $a$?', '["$-1$", "1", "2", "11"]'::jsonb, 12, null),
  ('667c08a7-011f-5fe9-ace0-48bc107fddb4', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', 'One side of a flat board has an area of 360 square inches. If a pressure of 40 pounds per square inch of area is exerted on this side of the board, what is the total force, in pounds, exerted on this side of the board?', '["9", "320", "400", "14,400"]'::jsonb, 13, null),
  ('5a7d730c-6826-550d-94dd-042a622fa884', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', 'Line $p$ is defined by $x - 38y = 38$. Line $w$ is parallel to line $p$ in the $xy$-plane. What is the slope of line $w$ ?', '["38", "$\\frac{1}{38}$", "$-\\frac{1}{38}$", "$-38$"]'::jsonb, 14, null),
  ('3ced3d86-4a7f-54f7-b81b-9762c8eac472', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', '$5∣x - 5∣ = 10$
What is the sum of the solutions to the given equation?', '["$-2$", "0", "10", "15"]'::jsonb, 15, null),
  ('6acc71c0-2c97-5435-8d3c-baf74fe3d3f1', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', 'If $4 + \frac{2(13-x)}{9} = 3(13 - x) + 4$, what is the value of $13 + x$?', '[]'::jsonb, 16, null),
  ('ebcd16d6-278d-5ad5-8170-f64a5d965041', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', '$y = x^{2} + 9x + 18$
$x + 6 = 10$
The solution to the given system of equations is $(x,y)$. What is the value of $y$?', '[]'::jsonb, 17, null),
  ('86f116eb-4cf1-5542-a6a4-392be792378b', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', 'In the $xy$-plane, circle $M$ is the graph of the equation $(x - 5)^{2} + (y - 6)^{2} = 4$. Circle $P$ has the same center as circle $M$ but has a radius that is twice the radius of circle $M$. Which equation represents circle $P$?', '["$(x - 5)^{2} + (y - 6)^{2} = 8$", "$(x - 5)^{2} + (y - 6)^{2} = 16$", "$(x - 10)^{2} + (y - 12)^{2} = 4$", "$(x - 10)^{2} + (y - 12)^{2} = 8$"]'::jsonb, 18, null),
  ('849f3122-a6a0-54f1-a817-6ce3d1af21d6', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', 'In the triangle shown, what is the value of $\sin x°$?', '[]'::jsonb, 19, '![figure](/q/may26/005.webp)'),
  ('3ae851ce-d72b-57da-ba59-31d1f58b5c54', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', '$y < -6x - 16$
$y > -4x - 12$
For which of the following tables are all the values of $x$ and their corresponding values of $y$ solutions to the given system of inequalities?', '["| x | y |\n| -5 | 6 |\n| -6 | 22 |\n| -8 | -6 |", "| x | y |\n| -5 | 7 |\n| -6 | 18 |\n| -8 | 30 |", "| x | y |\n| -5 | 9 |\n| -6 | 19 |\n| -8 | 30 |", "| x | y |\n| -5 | 14 |\n| -6 | 18 |\n| -8 | -6 |"]'::jsonb, 20, null),
  ('30139e7d-d2bb-58b3-abae-6e1e56d502af', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', 'An exponential function $f$ gives the estimated amount of an X-ray beam’s initial intensity remaining after passing through a $w$-centimeter-thick window made of beryllium. The function estimates that after passing through a 1.8-centimeter-thick window, the amount of the X-ray beam’s initial intensity remaining is 0.65. Which equation could define $f$?', '["$f(w) = 0.65(0.78)^{w-1.8}$", "$f(w) = 0.65(0.78)^{\\frac{w}{1.8}}$", "$f(w) = 0.65(1.8)^{w}$", "$f(w) = 1.8(0.65)^{w}$"]'::jsonb, 21, null),
  ('22b0c768-1a1e-51a5-a158-3db1e5fc51bb', '25db72cc-8a1a-59d9-a1ed-2fe0d2723591', 'For isosceles triangle $ABC$, $AB = BC = 64$, the measure of angle $ABC$ is $36°$, point $D$ lies on $\overline{BC}$, and $\angle BAC$ is bisected by $\overline{AD}$. Which of the following statements must be true?', '["$AB = AC = BC$", "$AD = BD = AC$", "$BD = CD = AC$", "$AB = BD = AD$"]'::jsonb, 22, '![figure](/q/may26/006.webp)')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('a6602bac-5b2c-5cf7-bb4b-11ba43d334c5', 0, null, '$15x^{2} - 15 \cdot 9 = 15x^{2} - 135$.'),
  ('39895eda-dd32-568e-917e-b093ac0ba492', 3, null, '$f(100) = 400 + 800 = 1,200$.'),
  ('c8586c4f-73eb-588a-8cc1-dd97b80ec549', null, array['102']::text[], '20% of 510 is $102$.'),
  ('f55fd532-0367-5df1-8903-a29bd10d908e', 0, null, 'Adding the equations gives $2y = 26$, so $y = 13$ and $x = 0$.'),
  ('3c5bc02c-bcf7-5c20-af3f-7dfa7acd213f', 3, null, 'Shifting up 3 adds 3 to the whole function: $(\frac{1}{9})^{x} + 4$.'),
  ('920df54d-c8d1-5ce5-855d-71c74152b721', null, array['78']::text[], '$g(-6) = |-60| + 18 = 78$.'),
  ('fd2dd355-1fca-5f35-8752-03a28f01c12c', null, array['747']::text[], 'Length $8(9) + 11 = 83$; area $83 \cdot 9 = 747$.'),
  ('13f63ded-dfc2-5eb7-bef4-a0a7fe875e49', 2, null, 'The line rises about 70 germinated seeds per 100 planted (slope about 0.7).'),
  ('40b5c46e-19b7-5919-8ef3-1e798ceb32fa', 0, null, 'Adding 8 shifts the line up; the slope stays 7.'),
  ('8d3a3a5f-3a7c-54e5-89bf-a315c5a8e531', 3, null, '$\frac{x + 11}{y} = z + 6$, so $z = \frac{x + 11}{y} - 6$.'),
  ('67533c94-42b9-53d1-aaa3-8cf052f24b66', 2, null, '$f(15) = 0$: after 15 days no free books remain.'),
  ('72c0ce89-1f3e-5de0-909a-411a5f6c50ef', 2, null, '$6a - 3 + 1 = 5a$ gives $a = 2$.'),
  ('667c08a7-011f-5fe9-ace0-48bc107fddb4', 3, null, '$360 \cdot 40 = 14,400$ pounds.'),
  ('5a7d730c-6826-550d-94dd-042a622fa884', 1, null, '$y = \frac{1}{38}x - 1$, so parallel lines have slope $\frac{1}{38}$.'),
  ('3ced3d86-4a7f-54f7-b81b-9762c8eac472', 2, null, '$|x - 5| = 2$ gives $x = 7$ or $x = 3$; the sum is $10$.'),
  ('6acc71c0-2c97-5435-8d3c-baf74fe3d3f1', null, array['26']::text[], 'With $u = 13 - x$: $\frac{2u}{9} = 3u$, so $u = 0$, $x = 13$ and $13 + x = 26$.'),
  ('ebcd16d6-278d-5ad5-8170-f64a5d965041', null, array['70']::text[], '$x = 4$, so $y = 16 + 36 + 18 = 70$.'),
  ('86f116eb-4cf1-5542-a6a4-392be792378b', 1, null, 'Radius doubles from 2 to 4, so $r^{2} = 16$ with the same center.'),
  ('849f3122-a6a0-54f1-a817-6ce3d1af21d6', null, array['16/29', '.5517', '0.551', '0.552']::text[], 'The side opposite $x°$ is 16 and the hypotenuse is 29: $\sin x° = \frac{16}{29}$.'),
  ('3ae851ce-d72b-57da-ba59-31d1f58b5c54', 2, null, 'The bounds are $8 < y < 14$ at $x = -5$, $12 < y < 20$ at $x = -6$, and $20 < y < 32$ at $x = -8$; only C fits all three.'),
  ('30139e7d-d2bb-58b3-abae-6e1e56d502af', 0, null, '$f(1.8) = 0.65(0.78)^{0} = 0.65$, and the function decreases with thickness.'),
  ('22b0c768-1a1e-51a5-a158-3db1e5fc51bb', 1, null, 'Base angles are $72°$, so the bisector makes $36°$ angles. Triangle $ABD$ has two $36°$ angles ($AD = BD$) and triangle $ADC$ has two $72°$ angles ($AD = AC$).')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

