insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('ea6e4ca6-fc91-5b3d-a306-545c94ee8b4f', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', '$(x + 9)(x - 12) = 0$
What is the positive solution to the given equation?', '[]'::jsonb, 1, null),
  ('8f2b3ebc-c43e-5076-b39c-8cd95ad2ec81', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', '$n(x) = 3(x + 8) + (x - 8)$
The function $n$ is defined as shown. For what value of $x$ is $n(x) = 52$?', '[]'::jsonb, 2, null),
  ('766aa237-22ff-5fa6-9061-05950b7341d3', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', 'The function $P(x) = 581(1.012)^{x}$ models the population of a certain town each year from 1957 through 1972, where $x$ is the number of years after 1957. Which of the following is the best interpretation of “$P(5)$ is approximately equal to 617” in this context?', '["The population of the town is estimated to be approximately 617 in 1962.", "The population of the town is estimated to be approximately 5 greater in 1962 than in 1957.", "The population of the town is estimated to be approximately 5 times greater in 1962 than in 1957.", "The population of the town is estimated to increase by approximately 617 every 5 years between 1957 and 1972."]'::jsonb, 3, null),
  ('cd3618cf-73cc-52fe-9443-23dfde8d2e78', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', '$g(x) = \frac{1}{2}(3)^{x}$
If the given function $g$ is graphed in the $xy$-plane, where $y = g(x)$, what is the $y$-intercept of the graph?', '["$(0,0)$", "$(0, \\frac{1}{2})$", "$(0, \\frac{3}{2})$", "$(0,3)$"]'::jsonb, 4, null),
  ('8b932ff2-8e4d-5db4-b2e3-b51424044028', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', '$8 - 4y = x$
$4 + 4y = x$
The solution to the given system of equations is $(x,y)$. What is the value of $x$?', '[]'::jsonb, 5, null),
  ('7ce42ad8-e2a9-5a53-b7a1-3b3e029a7c8e', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', 'In the figure, $\overline{BC}$ is parallel to $\overline{DE}$. If the length of $\overline{DE}$ is 129 and the length of $\overline{AE}$ is 215, what is the value of $\tan x°$?', '["$\\frac{129}{172}$", "$\\frac{129}{215}$", "$\\frac{172}{129}$", "$\\frac{215}{129}$"]'::jsonb, 6, '![figure](/q/may26/007.webp)'),
  ('0bc2705b-9152-5624-b69b-94c41ed2af74', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', '$-3x + 18px = 36$
In the given equation, $p$ is a constant. The equation has no solution. What is the value of $p$?', '["0", "$\\frac{1}{6}$", "$\\frac{2}{3}$", "2"]'::jsonb, 7, null),
  ('76850160-3501-5c29-bfa2-ee9da2db15b6', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', 'In the figure, line $AB$ is parallel to line $CD$, and line $AD$ intersects line $BC$ at $E$. If $y = 118$ and $z =$ $114$, what is the value of $x$?', '["52", "66", "128", "142"]'::jsonb, 8, '![figure](/q/may26/008.webp)'),
  ('ebf96d68-e3b1-57ee-a786-bcba47bcac6a', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', '$y = 3x^{2} + 22$
$y = px + 19$
In the given system of equations, $p$ is a positive constant. The graphs of the equations in the given system intersect at exactly one point, $(x,y)$, in the $xy$-plane. What is the value of $x$?', '["41", "25", "6", "1"]'::jsonb, 9, null),
  ('00dc8f57-003b-5923-8ee2-0148954faa12', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', 'The line segment shown in the $xy$-plane represents side $JK$ of isosceles triangle $JKL$, where side $JL$ is congruent to side $KL$. The perimeter of this triangle is $11\sqrt{13}$ units. What is the length, in units, of side $JL$ of this triangle?', '["$\\sqrt{13}$", "$3\\sqrt{13}$", "$4\\sqrt{13}$", "$8\\sqrt{13}$"]'::jsonb, 10, '![figure](/q/may26/009.webp)'),
  ('a9ab14e4-a8ba-529d-a84b-c3e73f0f85d6', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', 'The graph shows a linear relationship between $x$ and $y$. Which equation represents this relationship, where $R$ is a positive constant?', '["$Rx + 21y = 63$", "$Rx - 21y = -63$", "$21x + Ry = 63$", "$21x - Ry = -63$"]'::jsonb, 11, '![figure](/q/may26/010.webp)'),
  ('278e3bac-569a-59a8-b374-17d46ee6e7d8', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', 'According to the model, which of the following statements about the estimated resistivity of copper is true?', '["It increases at a rate of $\\frac{3}{5}$ nanoohm-meters per 100 kelvins.", "It increases at a rate of 6 nanoohm-meters per 100 kelvins.", "At 100 kelvins, it is 10 nanoohm-meters.", "From 200 kelvins to 400 kelvins, it decreases 12 nanoohm-meters."]'::jsonb, 12, 'The function $f$ models the resistivity of copper, in nanoohm-meters, as a function of the temperature $x$, in kelvins, of the copper. The graph of $y = f(x)$ is shown.

![figure](/q/may26/011.webp)'),
  ('8043b599-9118-5da1-b29b-bace74abb4a5', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', 'A community organization surveyed a random sample of residents of the community to estimate the percentage of residents who visit their local library at least once per month. From the survey, the organization estimates that $13%$ of residents of the community visit their local library at least once per month, with an associated margin of error of $3.4%$. The organization repeated the survey with a random sample of residents that was double the original sample size. Assuming the margins of error are calculated in the same way for both studies, which of the following is true about the margin of error associated with the estimate from the larger sample?', '["The margin of error is less than $3.4%$.", "The margin of error is $6.8%$.", "The margin of error is greater than $13%$.", "The margin of error is $26%$."]'::jsonb, 13, null),
  ('88e7124f-17cd-5524-95c9-0172043c085e', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', '$f(x) = (2x - 7)(2x + 11)$
What is the minimum value of the given function?', '["$-81$", "$-\\frac{11}{2}$", "$-4$", "$-1$"]'::jsonb, 14, null),
  ('f2c2cd53-9fc5-55bd-9a1e-a518cc7a8a0d', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', 'Each 3.0-ounce serving of cheddar cheese and each 1.2-ounce serving of tuna provides about 1 microgram of vitamin B12. If a total of 2.1 micrograms of vitamin B12 are consumed from eating $x$ ounces of cheese and $y$ ounces of tuna, which equation best represents this situation?', '["$1.2x + 3.0y = 2.1$", "$0.83x + 0.33y = 2.1$", "$3.0x + 1.2y = 2.1$", "$0.33x + 0.83y = 2.1$"]'::jsonb, 15, null),
  ('d73c42f9-752b-556b-8f92-525ca2a76477', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', 'Which expression is NOT a factor of $5,670x^{4} - 1,120$?', '["$9x^{2} + 4$", "$3x^{2} - 2$", "$3x + 2$", "70"]'::jsonb, 16, null),
  ('ac98ad38-893c-57e9-86ae-2bf88c5f95dd', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', '$-8x^{2} + bx - 98 = 0$
In the given equation, $b$ is a positive integer. The equation has no real solution. What is the largest possible value of $b$?', '[]'::jsonb, 17, null),
  ('fb7cea6e-58f1-5be1-b7b2-db6acd5d614b', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', 'A zoologist observed the nests of wood ducks in an area. Each year, the zoologist recorded the number of eggs in each of the first 35 nests that were observed and created a frequency table for the data set. Which of the following frequency tables represents the data set with the smallest standard deviation?', '["| Number of eggs | Frequency |\n| 7 | 8 |\n| 8 | 7 |\n| 9 | 5 |\n| 10 | 7 |\n| 11 | 8 |", "| Number of eggs | Frequency |\n| 7 | 7 |\n| 8 | 7 |\n| 9 | 7 |\n| 10 | 7 |\n| 11 | 7 |", "| Number of eggs | Frequency |\n| 7 | 2 |\n| 8 | 8 |\n| 9 | 15 |\n| 10 | 8 |", "| Number of eggs | Frequency |\n| 7 | 0 |\n| 8 | 5 |\n| 9 | 25 |\n| 10 | 5 |\n| 11 | 0 |"]'::jsonb, 18, null),
  ('b6cb3f53-2408-5b5e-8634-6ececddf390a', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', 'The area of a rectangular region is increasing at a rate of 220 square feet per hour. Which of the following is closest to this rate in <u>square meters per minute</u>? (Use 1 meter $= 3.28$ feet.)', '["0.34", "1.12", "12.03", "20.45"]'::jsonb, 19, null),
  ('5fb15335-fa07-5f37-a7b6-ca9767a46ad9', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', 'A researcher investigated two species of mites: a predator and its prey. At the start of a week, there was an equal number of the two species. At the end of the week, the number of prey had increased by $1400%$ of the number of prey at the start of the week, and the number of predators had increased by $170%$ of the number of predators at the start of the week. The number of predators at the end of the week was $p%$ less than the number of prey at the end of the week. What is the value of $p$?', '[]'::jsonb, 20, null),
  ('e1db039c-4550-5cef-93fc-7db85d0178ba', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', 'The function $f$ is a quadratic function. In the $xy$-plane, the graph of $y = f(x)$ has a vertex at $(1,3)$ and passes through the points $(2,29)$ and $(-1,107)$. What is the value of $f(-2) - f(0)$?', '["81", "133", "208", "237"]'::jsonb, 21, null),
  ('a2a67f8e-8861-5f67-86e6-dfa220b6819c', 'ea6c73f4-0476-55ad-bbf5-a7187e6c3313', 'The figure shown is a right rectangular pyramid, where $ℓ = 18$ units, $w = 9$ units, and $h = 12$ units. What is the surface area, in square units, of the pyramid?', '[]'::jsonb, 22, '![figure](/q/may26/012.webp)')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
