insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('ea6e4ca6-fc91-5b3d-a306-545c94ee8b4f', null, array['12']::text[], 'The solutions are $-9$ and $12$; the positive one is $12$.'),
  ('8f2b3ebc-c43e-5076-b39c-8cd95ad2ec81', null, array['9']::text[], '$3x + 24 + x - 8 = 4x + 16 = 52$, so $x = 9$.'),
  ('766aa237-22ff-5fa6-9061-05950b7341d3', 0, null, '$x = 5$ is 1962, and $P(5) ≈ 617$ is the estimated population then.'),
  ('cd3618cf-73cc-52fe-9443-23dfde8d2e78', 1, null, '$g(0) = \frac{1}{2}(3)^{0} = \frac{1}{2}$.'),
  ('8b932ff2-8e4d-5db4-b2e3-b51424044028', null, array['6']::text[], 'Adding the equations: $12 = 2x$, so $x = 6$.'),
  ('7ce42ad8-e2a9-5a53-b7a1-3b3e029a7c8e', 2, null, '$AD = \sqrt{215^{2} - 129^{2}} = 172$. Angle $x$ equals angle $E$ (parallel lines), so $\tan x° = \frac{AD}{DE} = \frac{172}{129}$.'),
  ('0bc2705b-9152-5624-b69b-94c41ed2af74', 1, null, '$x(18p - 3) = 36$ has no solution when $18p - 3 = 0$, so $p = \frac{1}{6}$.'),
  ('76850160-3501-5c29-bfa2-ee9da2db15b6', 2, null, 'Angle $ABE = 180 - 118 = 62$ and angle $BAE$ = angle $CDE = 180 - 114 = 66$, so angle $AEB = 52$ and $x = 180 - 52 = 128$.'),
  ('ebf96d68-e3b1-57ee-a786-bcba47bcac6a', 3, null, '$3x^{2} - px + 3 = 0$ has one solution when $p^{2} = 36$, so $p = 6$ and $x = \frac{6}{6} = 1$.'),
  ('00dc8f57-003b-5923-8ee2-0148954faa12', 2, null, '$JK = \sqrt{9^{2} + 6^{2}} = 3\sqrt{13}$, so $JL + KL = 8\sqrt{13}$ and $JL = 4\sqrt{13}$.'),
  ('a9ab14e4-a8ba-529d-a84b-c3e73f0f85d6', 2, null, 'The line passes through $(0,9)$ and $(3,0)$: $3x + y = 9$, or $21x + 7y = 63$.'),
  ('278e3bac-569a-59a8-b374-17d46ee6e7d8', 1, null, 'The line rises about 30 nanoohm-meters per 500 kelvins: 6 per 100 kelvins.'),
  ('8043b599-9118-5da1-b29b-bace74abb4a5', 0, null, 'A larger random sample gives a smaller margin of error.'),
  ('88e7124f-17cd-5524-95c9-0172043c085e', 0, null, 'The zeros are $3.5$ and $-5.5$, so the vertex is at $x = -1$: $f(-1) = (-9)(9) = -81$.'),
  ('f2c2cd53-9fc5-55bd-9a1e-a518cc7a8a0d', 3, null, 'Cheese gives $\frac{x}{3.0} ≈ 0.33x$ and tuna $\frac{y}{1.2} ≈ 0.83y$ micrograms.'),
  ('d73c42f9-752b-556b-8f92-525ca2a76477', 1, null, '$70(81x^{4} - 16) = 70(9x^{2} + 4)(3x - 2)(3x + 2)$; $3x^{2} - 2$ is not a factor.'),
  ('ac98ad38-893c-57e9-86ae-2bf88c5f95dd', null, array['55']::text[], 'No real solution: $b^{2} - 4(8)(98) < 0$, so $b^{2} < 3,136$ and $b < 56$. The largest integer is 55.'),
  ('fb7cea6e-58f1-5be1-b7b2-db6acd5d614b', 3, null, 'Most values sit at 9 and none are farther than 1 from it.'),
  ('b6cb3f53-2408-5b5e-8634-6ececddf390a', 0, null, '$\frac{220}{3.28^{2}} ≈ 20.45$ square meters per hour, about $0.34$ per minute.'),
  ('5fb15335-fa07-5f37-a7b6-ca9767a46ad9', null, array['82']::text[], 'Prey end at $15N$ and predators at $2.7N$: $\frac{15 - 2.7}{15} = 0.82$, so $p = 82$.'),
  ('e1db039c-4550-5cef-93fc-7db85d0178ba', 2, null, '$f(x) = a(x - 1)^{2} + 3$ with $f(2) = 29$ gives $a = 26$. $f(-2) = 237$ and $f(0) = 29$: the difference is $208$.'),
  ('a2a67f8e-8861-5f67-86e6-dfa220b6819c', null, array['527.7', '527.69', '527.688']::text[], 'Base $18 \cdot 9 = 162$. Faces on the 9 side: slant $\sqrt{12^{2} + 9^{2}} = 15$, area $2 \cdot \frac{1}{2} \cdot 9 \cdot 15 = 135$. Faces on the 18 side: slant $\sqrt{12^{2} + 4.5^{2}} ≈ 12.816$, area $≈ 230.69$. Total $≈ 527.7$.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;
